package com.example.budgetapp.data;
import androidx.room.Room;
import androidx.test.core.app.ApplicationProvider;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import com.example.budgetapp.data.entity.*;
import com.example.budgetapp.processing.*;
import com.example.budgetapp.processing.LedgerTypes.*;
import java.time.*;
import org.junit.*;
import org.junit.runner.RunWith;
import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class) public class CategoryRepositoryTest {
 private LedgerDatabase db;private CategoryRepository repo;private ManualLedgerRepository manual;
 private static final String FOOD="00000000-0000-0000-0000-000000000003";
 @Before public void setUp(){db=Room.inMemoryDatabaseBuilder(ApplicationProvider.getApplicationContext(),LedgerDatabase.class).addCallback(LedgerDatabase.CALLBACK).allowMainThreadQueries().build();repo=new CategoryRepository(db,Clock.systemUTC());manual=new ManualLedgerRepository(db,Clock.systemUTC());}
 @After public void close(){db.close();}
 private CategoryRuleEntity rule(){var r=new CategoryRuleEntity();r.id="rule";r.categoryId=FOOD;r.matchType="EXACT";r.merchantPattern="午间面馆";r.enabled=true;return r;}
 private String tx(String key){return manual.save(key,new TransactionDraft(Kind.EXPENSE,100,100,TimePrecision.DAY,"午间面馆","OTHER","scope",null,""),true).transactionId;}
 @Test public void lockedHistoryIsExcludedAndRulesDoNotRewriteHistory(){String id=manual.save("one",new TransactionDraft(Kind.EXPENSE,100,100,TimePrecision.DAY,"午间面馆","OTHER","scope",LedgerTypes.UNCATEGORIZED_EXPENSE,""),true).transactionId;repo.upsertRule(rule());assertEquals(LedgerTypes.UNCATEGORIZED_EXPENSE,db.ledgerDao().find(id).categoryId);assertEquals(0,repo.previewReclassification("rule").changes.size());}
 @Test public void previewRejectsStaleRevisionsWithoutPartialUpdates(){String one=tx("one"),two=tx("two");for(String id:new String[]{one,two}){var t=db.ledgerDao().find(id);t.userLockedFields="[]";t.categoryOrigin="DEFAULT";db.ledgerDao().update(t);}repo.upsertRule(rule());var preview=repo.previewReclassification("rule");assertEquals(2,preview.changes.size());var changed=db.ledgerDao().find(two);changed.revision++;db.ledgerDao().update(changed);assertEquals(ManualLedgerRepository.WriteResult.Status.STALE,repo.applyReclassification(preview).status);assertEquals(LedgerTypes.UNCATEGORIZED_EXPENSE,db.ledgerDao().find(one).categoryId);var fresh=repo.previewReclassification("rule");assertEquals(ManualLedgerRepository.WriteResult.Status.APPLIED,repo.applyReclassification(fresh).status);assertEquals(FOOD,db.ledgerDao().find(one).categoryId);assertNotNull(db.ledgerDao().find(one).recentPreviousValuesJson);}
 @Test public void archivingDisablesRulesAndPreservesHistory(){repo.upsertRule(rule());repo.archiveCategory(FOOD);assertTrue(db.categoryDao().find(FOOD).archived);assertFalse(db.categoryDao().rules().get(0).enabled);assertThrows(IllegalArgumentException.class,()->repo.archiveCategory(LedgerTypes.UNCATEGORIZED_EXPENSE));repo.renameCategory(FOOD,"外食");assertEquals("外食",db.categoryDao().find(FOOD).name);}
 @Test public void ruleChangeInvalidatesPreview(){repo.upsertRule(rule());var preview=repo.previewReclassification("rule");repo.setRuleEnabled("rule",false);assertEquals(ManualLedgerRepository.WriteResult.Status.STALE,repo.applyReclassification(preview).status);}
 @Test public void manualRuleSuggestionRespectsExplicitCategory(){repo.upsertRule(rule());String auto=tx("auto");assertEquals(FOOD,db.ledgerDao().find(auto).categoryId);var explicit=new TransactionDraft(Kind.EXPENSE,200,200,TimePrecision.DAY,"午间面馆","OTHER","scope",LedgerTypes.UNCATEGORIZED_EXPENSE,"");String id=manual.save("explicit",explicit,true).transactionId;assertEquals(LedgerTypes.UNCATEGORIZED_EXPENSE,db.ledgerDao().find(id).categoryId);}
 @Test public void untouchedManualCategoryCanBeReclassifiedByAnExplicitPreview(){tx("unclassified");repo.upsertRule(rule());assertEquals(1,repo.previewReclassification("rule").changes.size());}
 @Test public void newCategoriesKeepTheirFlowAndAppendToExistingOrder(){var expense=repo.createCategory(" 学习 ",Kind.EXPENSE);var income=repo.createCategory("学习",Kind.INCOME);assertEquals("学习",expense.name);assertEquals("EXPENSE",expense.flowScope);assertEquals("INCOME",income.flowScope);assertNotEquals(expense.id,income.id);assertFalse(expense.archived);assertTrue(income.sortOrder>expense.sortOrder);assertEquals(expense.id,db.categoryDao().find(expense.id).id);}
 @Test public void creationRejectsInvalidAndActiveDuplicateNames(){assertThrows(IllegalArgumentException.class,()->repo.createCategory("  ",Kind.EXPENSE));assertThrows(IllegalArgumentException.class,()->repo.createCategory("\u3000\u00a0",Kind.EXPENSE));assertThrows(IllegalArgumentException.class,()->repo.createCategory("有效",null));repo.createCategory("新类别",Kind.EXPENSE);assertThrows(CategoryRepository.DuplicateCategoryName.class,()->repo.createCategory("\u3000新类别\u00a0",Kind.EXPENSE));assertThrows(CategoryRepository.DuplicateCategoryName.class,()->repo.createCategory("工资",Kind.INCOME));assertEquals(6,repo.categories().size());}
 @Test public void archivedNameCanBeReusedWithoutChangingHistory(){var original=repo.createCategory("学习",Kind.EXPENSE);repo.archiveCategory(original.id);var replacement=repo.createCategory("学习",Kind.EXPENSE);assertNotEquals(original.id,replacement.id);assertTrue(db.categoryDao().find(original.id).archived);assertFalse(db.categoryDao().find(replacement.id).archived);}
 @Test public void defaultsFollowCategoriesInInsertionOrder(){var daily=repo.createCategory("日常",Kind.EXPENSE);var study=repo.createCategory("学习",Kind.EXPENSE);var rows=repo.categories();assertEquals(FOOD,rows.get(0).id);assertEquals(daily.id,rows.get(3).id);assertEquals(study.id,rows.get(4).id);assertEquals(LedgerTypes.UNCATEGORIZED_EXPENSE,rows.get(rows.size()-2).id);assertEquals(LedgerTypes.UNCATEGORIZED_INCOME,rows.get(rows.size()-1).id);repo.renameCategory(daily.id,"生活日常");assertEquals(daily.id,repo.categories().get(3).id);}
}
